mapper.select:
select code, name, subject, status, remark, update_by, update_time from mail_template
and name like concat('%', #{name}, '%') and status = #{status}
order by code

mapper.update:
update mail_template
name = #{name}, subject = #{subject}, content = #{content}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
where code = #{code}
